import {Icon} from './icons.jsx';
import React,{useState,useRef,useEffect,useLayoutEffect,useContext,createContext} from 'react';
import {products,services,pages,productImage} from './data.js';
import {mountProductPhoto,openProductPhoto} from './lib/product-photo.js';
import {createEquipment} from './lib/equipment.js';
import {createFacility} from './lib/scene.js';
import {animateSwap} from './lib/motion.js';
export const ImageContext=createContext(()=>{});
export function Button({href,children,light=false}){return <a className={`button${light?' light':''}`} href={href}>{children}<span><Icon name="arrowUpRight"/></span></a>}
export function FittedPhoto({src,alt,top=18,bottom=18,padding=18}){
 const host=useRef(null);
 useLayoutEffect(()=>{const photo=mountProductPhoto(host.current,src,{alt,top,bottom,padding});return ()=>{photo.destroy();photo.element.remove();};},[src,alt,top,bottom,padding]);
 return <div className="react-photo-host" ref={host}/>;
}
export function PhotoButton({src,alt,cover=false}){const show=useContext(ImageContext);return <button type="button" className="gallery-zoom" aria-label={`View ${alt||'product image'} full size`} onClick={()=>show(src,alt)}>{cover?<img src={src} alt={alt}/>:<FittedPhoto src={src} alt={alt} top={20} bottom={55} padding={20}/>}<span>View full size ↗</span></button>}
export function ProductCard({product:p}){
 const illustrated=['airhandlingunit.html','cleanroompanels.html'].includes(p[0]);const src=p[0]==='airhandlingunit.html'?'assets/premium/ahu-studio.png':p[0]==='cleanroompanels.html'?'assets/premium/cleanroom-hero.png':productImage(p);
 return <a href={p[0]} className={`product-card${illustrated?' product-illustrated':''}`}><div className="product-image"><span className="product-badge">{illustrated?'Concept visualisation':'Original product image'} <span><Icon name="shieldCheck" size={18}/></span></span>{illustrated?<img src={src} alt={`${p[1]} — concept visualisation`} loading="lazy"/>:<FittedPhoto src={src} alt={p[1]} top={60} bottom={35}/>}<span className="product-open" aria-hidden="true">↗</span></div><div className="product-info"><small>{p[2]}</small><h3>{p[1]}</h3><p>{p[4]}</p><span className="product-bottom">Explore product &amp; 3D view <span><Icon name="arrowUpRight"/></span></span></div></a>;
}
export function Catalogue(){
 const [category,setCategory]=useState('All products'),[query,setQuery]=useState('');const grid=useRef(null);const shown=products.filter(p=>(category==='All products'||p[2]===category)&&`${p[1]} ${p[2]} ${p[4]}`.toLowerCase().includes(query.trim().toLowerCase()));
 useEffect(()=>{animateSwap(grid.current);},[category,query]);
 return <section className="section"><div className="wrap"><div className="catalogue-tools"><div className="filters" role="group" aria-label="Product categories">{['All products',...new Set(products.map(p=>p[2]))].map(c=><button key={c} className="filter" data-filter={c} aria-pressed={category===c} onClick={()=>setCategory(c)}>{c}</button>)}</div><label className="search"><input type="search" aria-label="Search products" placeholder="Search the catalogue" value={query} onChange={e=>setQuery(e.target.value)}/><span aria-hidden="true"><Icon name="search"/></span></label></div><p className="results-count" aria-live="polite">{shown.length} of {products.length} products</p><div className="product-grid" id="catalogue" ref={grid}>{shown.length?shown.map(p=><ProductCard key={p[0]} product={p}/>):<div className="empty"><h3>No products found</h3><p>Try another search or select All products.</p></div>}</div></div></section>;
}
export function EnquiryForm(){
 const selected=new URLSearchParams(location.search).get('product')||'General enquiry';const [prepared,setPrepared]=useState(null),[copied,setCopied]=useState(false),[copyFailed,setCopyFailed]=useState(false);
 const submit=e=>{e.preventDefault();const d=new FormData(e.currentTarget);const body=`Name: ${d.get('name')}\nCompany: ${d.get('company')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')}\nInterest: ${d.get('interest')}\n\nProject requirements:\n${d.get('message')}`;setPrepared({body,href:`mailto:info@aemsinfra.com?subject=${encodeURIComponent('Project enquiry — '+d.get('interest'))}&body=${encodeURIComponent(body)}`});setCopied(false);setCopyFailed(false);};
 return <form className="contact-form" onSubmit={submit}><h3>Tell us about your project.</h3><p>Share a few details to prepare an enquiry for our engineering team.</p><div className="form-grid">{[['name','Your name *','Full name','text','name',true],['company','Company','Organisation name','text','organization',false],['email','Work email *','you@company.com','email','email',true],['phone','Phone number','+91','tel','tel',false]].map(([name,label,placeholder,type,autoComplete,required])=><div className="field" key={name}><label htmlFor={name}>{label}</label><input id={name} name={name} placeholder={placeholder} type={type} autoComplete={autoComplete} required={required}/></div>)}<div className="field full"><label htmlFor="interest">I’m interested in</label><select id="interest" name="interest" defaultValue={selected}>{['General enquiry',...services.slice(0,5).map(s=>s[1]),...products.map(p=>p[1])].map(s=><option key={s}>{s}</option>)}</select></div><div className="field full"><label htmlFor="message">Project requirements *</label><textarea id="message" name="message" required placeholder="Tell us about your facility, equipment or project requirements…"/></div></div><button type="submit" className="button">Prepare email enquiry <span><Icon name="arrowUpRight"/></span></button><p className="form-note">Opens your email app with these details. Review and send your enquiry there.</p><div className="form-status" role="status">{prepared&&<>Your enquiry is ready. <a className="text-link" href={prepared.href}>Open your email app ↗</a> or copy the enquiry below. <button type="button" className="filter" id="copy-enquiry" onClick={async()=>{try{await navigator.clipboard.writeText(prepared.body);setCopied(true);}catch{setCopyFailed(true);}}}>{copied?'Copied ✓':'Copy enquiry'}</button>{copyFailed&&<textarea readOnly aria-label="Prepared enquiry" style={{width:'100%',minHeight:200}} value={prepared.body}/>}</>}</div></form>;
}
function EquipmentStage({product:p,discovery=false}){
 const stage=useRef(null);const paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
 useLayoutEffect(()=>{const viewer=createEquipment(stage.current.querySelector('.equipment-canvas'),p[0],discovery?(pages[p[0]]?.images?.[0]||productImage(p)):productImage(p));return ()=>viewer?.destroy?.();},[p,discovery]);
 return <div className="equipment-stage" ref={stage}><div className="equipment-tools" role="group" aria-label={discovery?'Equipment studio controls':'Product viewer'}><button data-equipment="model" aria-pressed="true"><Icon name="cube" size={17}/>3D model</button><button data-equipment="photo" aria-pressed="false">{discovery?'Original photo':'Product photo'}</button><button data-equipment="motion" aria-pressed={paused}><Icon name="play" className="play-icon" size={17}/><Icon name="pause" className="pause-icon" size={17}/><span data-motion-label>{paused?'Play motion':'Pause motion'}</span></button></div><div className="equipment-canvas" role="img" tabIndex="0" aria-label={`Conceptual 3D model of ${p[1]}. Drag to rotate, or use left and right arrow keys.`}/><span className="equipment-hint">Drag to rotate · Use the zoom controls to inspect</span><div className="viewer-zoom"><button data-equipment="zoom-in" aria-label="Zoom in"><Icon name="zoomIn"/></button><button data-equipment="zoom-out" aria-label="Zoom out"><Icon name="zoomOut"/></button><button data-equipment="reset" aria-label="Reset product view"><Icon name="rotate"/></button><button data-equipment="full-size" aria-label="Open original product photo full size"><Icon name="expand"/></button></div></div>;
}
export function ProductShowcase({product:p}){return <section className="equipment-showcase"><div className="wrap equipment-layout"><EquipmentStage product={p}/><div className="equipment-copy"><h2>Product overview</h2><p>{p[4]}</p><a className="text-link" href="#technical-details">View technical details <span><Icon name="arrowDown"/></span></a><div className="equipment-note">Concept model for illustration. Refer to the original specifications and confirm construction details with the AEMS engineering team.</div></div></div></section>}
function Facility({initialMode='all'}){
 const shell=useRef(null);const paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
 useLayoutEffect(()=>{const viewer=createFacility(shell.current.querySelector('.scene-canvas'));if(initialMode!=='all')viewer?.setMode(initialMode);return ()=>viewer?.destroy?.();},[initialMode]);
 return <div className="scene-shell" ref={shell}><div className="scene-canvas" role="img" tabIndex="0"/><div className="scene-toolbar" role="group" aria-label="Explore the 3D facility"><button data-scene="all" aria-pressed="true"><Icon name="cube" size={17}/>Facility</button><button data-scene="air" aria-pressed="false"><Icon name="wind" size={17}/>Airflow</button><button data-scene="exploded" aria-pressed="false"><Icon name="layers" size={17}/>Exploded</button></div><div className="scene-status"><button data-scene="motion" className="motion-button" aria-pressed={paused}>{paused?'Play motion':'Pause motion'}</button><button data-scene="reset" className="motion-button"><Icon name="rotate" size={17}/>Reset view</button></div></div>;
}
export function FacilityWorld(){return <div className="facility-studio-world"><Facility/><div className="studio-legend"><span><i/>Clean room envelope</span><span><i/>Air treatment &amp; distribution</span><span><i/>Integrated utilities</span><small>Concept model · Drag or use arrow keys to rotate</small></div></div>}
export function ServiceExperience({route}){const service=services.find(s=>s[0]===route);return <section className="service-experience"><div className="wrap service-world"><Facility initialMode={route==='hvacservices.html'?'air':route==='mepcontractors.html'?'exploded':'all'}/><div className="service-world-copy"><div className="eyebrow">Engineering, from a new perspective</div><h2>{service?.[1]||'Your facility. One connected environment.'}</h2><p>{service?.[2]||'Clean rooms, air handling and MEP systems—explore how the layers of a facility work together.'}</p><a href="#service-details" className="text-link">Explore the full service <span><Icon name="arrowDown"/></span></a><small>Interactive concept environment. Drag or use the arrow keys to rotate. Switch layers to explore the engineering.</small></div></div></section>}
const solutionMedia=['assets/premium/cleanroom-hero.png','assets/premium/ahu-studio.png','assets/img/mep-home.png','assets/img/validations.png','assets/img/facility.png'];
const solutionText=['Modular clean rooms designed around your process. Panels, doors, equipment and environmental control, coordinated from concept to commissioning.','Environmental control that works for your facility. Design, supply, installation and commissioning of HVAC systems, with retrofit and maintenance support.','Mechanical, electrical and plumbing engineering under one roof. Connected building services with one coordinated approach to project delivery.','Know how your environment performs. Clean room testing, filter integrity checks, environmental measurements and clear technical documentation.','Keep critical utilities and process equipment working with dedicated engineering support, planned maintenance and equipment qualification.'];
export function Solutions(){const [index,setIndex]=useState(0);const panel=useRef(null);const s=services[index];useEffect(()=>{animateSwap(panel.current);},[index]);return <><div className="solution-tabs" role="tablist" aria-label="Engineering solutions">{services.slice(0,5).map((service,i)=><button key={service[0]} role="tab" id={`solution-tab-${i}`} data-solution={i} aria-controls="solution-panel" aria-selected={index===i} tabIndex={index===i?0:-1} onClick={()=>setIndex(i)} onKeyDown={e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?4:(i+(e.key==='ArrowRight'?1:4))%5;setIndex(next);document.getElementById(`solution-tab-${next}`).focus();}}>{service[1]}</button>)}</div><div className="solution-feature" id="solution-panel" role="tabpanel" aria-labelledby={`solution-tab-${index}`} ref={panel}><div className="solution-feature-image"><img src={solutionMedia[index]} alt={`${s[1]} ${index<2?'concept visualisation':'from the AEMS service portfolio'}`}/><span>{index<2?'ENGINEERING VISUALISATION':'AEMS SERVICE PORTFOLIO'}</span></div><div className="solution-feature-copy"><span className="feature-number">0{index+1} / OUR CAPABILITIES</span><h3>{s[1]}</h3><p>{solutionText[index]}</p><Button href={s[0]}>Explore this solution</Button><a href={'contact.html?product='+encodeURIComponent(s[1])}>Discuss your requirements ↗</a></div></div></>}
export function EquipmentDiscovery(){const [index,setIndex]=useState(11);const stage=useRef(null);const p=products[index];useEffect(()=>{animateSwap(stage.current,{media:true});},[index]);return <div className="discovery-layout"><div className="discovery-copy"><span className="studio-label">3D EQUIPMENT EXPLORER</span><h3 id="discovery-title">{p[1]}</h3><p id="discovery-description">{p[4]}</p><div className="discovery-selector" role="group" aria-label="Choose equipment to explore">{[[11,'Air handling unit'],[8,'Air shower'],[6,'Pass box'],[0,'Clean room panels']].map(([value,label],i)=><button key={value} data-discovery={value} aria-pressed={index===value} onClick={()=>setIndex(value)}><span>0{i+1}</span>{label}<Icon name="arrowUpRight"/></button>)}</div><a className="button" id="discovery-link" href={p[0]}>View full product <span><Icon name="arrowUpRight"/></span></a><small>Illustrative 3D models. Original specifications and product photographs are available on each product page.</small></div><div className="discovery-viewport" id="discovery-stage" ref={stage}><EquipmentStage key={p[0]} product={p} discovery/></div></div>}
